def detect_root() -> Path:
    root = Path.cwd().resolve()

    required = [
        root / "research",
        root / "final_pipeline",
        root / "application",
        root
        / "final_pipeline/src/fraud_screening/training/factory.py",
        root
        / "final_pipeline/src/fraud_screening/training/outputs.py",
        root
        / "final_pipeline/src/fraud_screening/training/preprocessing_fit.py",
        root
        / "final_pipeline/src/fraud_screening/training/trainer.py",
        root
        / "final_pipeline/src/fraud_screening/training/persistence.py",
        root
        / "final_pipeline/artifacts/official/model/model.joblib",
        root
        / "final_pipeline/artifacts/official/preprocessing/preprocessing_state.json",
        root
        / "final_pipeline/artifacts/official/manifest/artifact_manifest.json",
    ]

    if not all(path.exists() for path in required):
        raise RuntimeError(
            "Repository training foundation or official artifact set is incomplete."
        )

    return root


def main() -> None:
    parser = argparse.ArgumentParser()

    parser.add_argument(
        "--execute",
        action="store_true",
        help=(
            "Create canonical training-bundle loader, rebuild orchestrator, "
            "training CLI and unit tests."
        ),
    )

    args = parser.parse_args()

    root = detect_root()
    init_path = root / INIT_REL

    collisions = [
        relative
        for relative in NEW_FILES
        if (root / relative).exists()
    ]

    init_matches = (
        init_path.is_file()
        and init_path.read_text(
            encoding="utf-8"
        )
        == EXPECTED_INIT
    )

    print("=" * 92)
    print(
        "M9.6 REBUILD TRAINING COMMAND — CANONICAL BUNDLE CONTRACT"
    )
    print("=" * 92)
    print("Project root:", root)
    print(
        "Mode:",
        "EXECUTE — GUARDED SOURCE/TEST CREATION"
        if args.execute
        else "DRY RUN — NO FILES WRITTEN",
    )

    print("\n[1] training/__init__.py guard")
    print(
        " - exact expected current content:",
        "YES" if init_matches else "NO",
    )

    print("\n[2] Planned files")
    for relative in NEW_FILES:
        print(" -", relative)

    print("\n[3] Collision gate")
    print(" - collisions:", len(collisions))
    for relative in collisions:
        print("   *", relative)

    print("\n[4] Canonical bundle contract")
    print(" - profile: W_SHORT")
    print(" - temporal window: 2018-01-01 <= Timestamp < 2019-01-01")
    print(" - rows: 1,721,615")
    print(" - fraud rows: 2,491")
    print(" - semantic features: 10")
    print(" - target: separate int8 binary array")
    print(" - file fingerprints: REQUIRED")
    print(" - global timestamp sort: NOT REQUIRED")
    print(" - row order integrity: locked by file SHA-256")
    print(" - bundle under research/: FORBIDDEN")
    print(" - pickle/object arrays: FORBIDDEN")

    print("\n[5] Training command behavior")
    print(" - default mode: bundle validation only")
    print(" - --execute: fit preprocessing + model")
    print(" - --execute output: final_pipeline/outputs/rebuilds/<run_id>/")
    print(" - existing run overwrite: FORBIDDEN")
    print(" - predict()/predict_proba(): NO")
    print(" - official promotion: NO")
    print(" - official M8 metric inheritance: NO")
    print(" - official artifact SHA rechecked after execute: YES")

    print("\n[6] Milestone boundary")
    print(" - raw CSV -> canonical bundle producer: NOT added here")
    print(" - per-User+Card causal order belongs to bundle production")
    print(" - raw dataset replay remains M9.7")
    print(" - runtime dependency on research/: NONE")

    print("\n[7] Bootstrap side effects")
    print(" - dry-run source write: NO")
    print(" - execute source/test write: YES")
    print(" - execute model.fit(): NO")
    print(" - execute preprocessing fit: NO")
    print(" - execute rebuild artifact write: NO")
    print(" - official artifact modification: NO")
    print(" - research modification: NO")
    print(
        " - unit tests after bootstrap: synthetic fit + temp-dir persistence only"
    )

    if collisions or not init_matches:
        print("\nRESULT: STOP")
        print("No files were written.")
        raise SystemExit(1)

    if not args.execute:
        print("\nDRY-RUN RESULT: PASS")
        print("Execute with:")
        print(
            "python bootstrap_rebuild_training_command.py --execute"
        )
        print("=" * 92)
        return

    created = []
    original_init = (
        init_path.read_text(
            encoding="utf-8"
        )
    )

    try:
        for relative, content in NEW_FILES.items():
            path = root / relative
            path.parent.mkdir(
                parents=True,
                exist_ok=True,
            )
            path.write_text(
                content,
                encoding="utf-8",
            )
            created.append(path)

        init_path.write_text(
            UPDATED_INIT,
            encoding="utf-8",
        )

    except Exception:
        for path in reversed(created):
            try:
                path.unlink()
            except OSError:
                pass

        try:
            init_path.write_text(
                original_init,
                encoding="utf-8",
            )
        except OSError:
            pass

        raise

    print("\n[8] Created")
    for path in created:
        print(
            " -",
            path.relative_to(root),
        )

    print("\n[9] Updated")
    print(" -", INIT_REL)

